import{_ as n,o as a,c as r,a3 as t}from"./chunks/framework.z_KJ15Ep.js";const o=JSON.parse('{"title":"Daten aufbewahren, prüfen und löschen","description":"","frontmatter":{},"headers":[],"relativePath":"administration/datenschutz.md","filePath":"administration/datenschutz.md"}'),s={name:"administration/datenschutz.md"};function h(u,e,l,i,d,c){return a(),r("div",null,[...e[0]||(e[0]=[t('<h1 id="daten-aufbewahren-prufen-und-loschen" tabindex="-1">Daten aufbewahren, prüfen und löschen <a class="header-anchor" href="#daten-aufbewahren-prufen-und-loschen" aria-label="Permalink to &quot;Daten aufbewahren, prüfen und löschen&quot;">​</a></h1><p>Unterscheiden Sie eine Prüfung von der tatsächlichen Löschung und einen Löschvermerk vom endgültigen Entfernen eines Datensatzes. Die <a href="/schild3/schueler/datenschutzhinweise-verwaltung-hilfe.html">Datenschutzhinweise</a> benennen die zugrunde liegenden Regelungsbereiche und Verantwortlichkeiten.</p><h2 id="aufbewahrungsfristen-prufen" tabindex="-1">Aufbewahrungsfristen prüfen <a class="header-anchor" href="#aufbewahrungsfristen-prufen" aria-label="Permalink to &quot;Aufbewahrungsfristen prüfen&quot;">​</a></h2><p>Die Funktion <a href="/schild3/schueler/daten-gemaess-loeschfristen-loeschen-verwaltung-werkzeuge.html">Daten auf abgelaufene Aufbewahrungsfristen prüfen und löschen</a> führt zunächst die Prüfung aus und zeigt gefundene Daten an. Das Löschen wird anschließend gesondert angestoßen.</p><h2 id="einzelne-schulerdatensatze-behandeln" tabindex="-1">Einzelne Schülerdatensätze behandeln <a class="header-anchor" href="#einzelne-schulerdatensatze-behandeln" aria-label="Permalink to &quot;Einzelne Schülerdatensätze behandeln&quot;">​</a></h2><p>Die Anleitung <a href="/schild3/schueler/schueler-loeschen-und-wiederherstellen-tutorial.html">Schülerdatensätze löschen und wiederherstellen</a> erklärt Löschvermerk, Papierkorb und Rücknahme. Der Gruppenprozess <a href="/schild3/suchen-gruppenprozesse/schueler-datensaetze-loeschen-gruppenprozesse-allgemein.html">Schülerdatensätze endgültig löschen</a> entfernt die ausgewählten Datensätze endgültig.</p><h2 id="alte-schuljahre-aufraumen" tabindex="-1">Alte Schuljahre aufräumen <a class="header-anchor" href="#alte-schuljahre-aufraumen" aria-label="Permalink to &quot;Alte Schuljahre aufräumen&quot;">​</a></h2><p>Das Werkzeug <a href="/schild3/schueler/aufraeumen-verwaltung-werkzeuge.html">Alte Schuljahresdaten aufräumen</a> entfernt Daten eines ausgewählten Schuljahres unwiderruflich. Beachten Sie die Auswirkungen auf Leistungsdaten und Verknüpfungen sowie die vorherige Datensicherung.</p><p>Die beschriebenen Programmfunktionen ersetzen nicht die Prüfung der für die Schule geltenden Aufbewahrungs- und Anbietungspflichten.</p>',9)])])}const g=n(s,[["render",h]]);export{o as __pageData,g as default};
